"""Editorial ENTENDA rows for CC-10, arts. 905-972."""
from __future__ import annotations


def row(says, means, example, warning, term, definition):
    return {"target": None, "o_que_diz": says, "o_que_significa": means, "exemplo_pratico": example, "atencao": warning, "palavras_dificeis": [{"termo": term, "explicacao": definition}]}


ROWS = {
    "905": row("Quem possui título ao portador pode exigir a prestação nele indicada mediante simples apresentação, mesmo que o título tenha circulado contra a vontade do emitente.", "A posse e a apresentação legitimam o portador a cobrar, pois o documento não identifica nominalmente o credor.", "Quem apresenta título ao portador no vencimento pede ao devedor o pagamento indicado.", "A regra pressupõe título válido e não elimina defesas legalmente admitidas. A circulação involuntária não se confunde com nulidade do título.", "Título ao portador", "título que legitima quem o possui e o apresenta"),
    "906": row("O devedor só pode opor ao portador defesa fundada em relação pessoal com ele ou na nulidade da própria obrigação.", "A circulação do título limita as defesas contra o portador, preservando a confiança na cobrança documental.", "Devedor prova que já pagou ao atual portador ou que sua obrigação é nula.", "Defesas existentes apenas contra possuidores anteriores, em regra, não atingem o portador atual de boa-fé.", "Exceção pessoal", "defesa decorrente da relação direta entre devedor e credor atual"),
    "907": row("É nulo o título ao portador cuja emissão não esteja autorizada por lei especial.", "A autonomia privada não basta para criar livremente documento pagável a qualquer apresentante; é necessária previsão legal específica.", "Documento emitido como título ao portador sem autorização legal não vale como tal.", "A nulidade do título não resolve automaticamente eventuais relações causais entre as partes, que devem ser examinadas separadamente.", "Autorização legal", "permissão expressa dada por norma para emissão do título"),
    "908": row("O possuidor de título rasgado ou danificado, mas ainda identificável, pode exigir substituição do emitente, devolvendo o original e pagando as despesas.", "A deterioração não elimina o direito quando ainda é possível reconhecer o documento e evitar duplicidade de circulação.", "Portador entrega ao emitente título parcialmente rasgado e arca com o custo da nova via.", "A substituição exige identificação segura e restituição do documento anterior; mero relato de perda segue regime diferente.", "Título dilacerado", "documento rasgado ou materialmente danificado"),
    "909": row("Quem perde, extravia ou sofre desapossamento injusto de título pode pedir judicialmente outro e impedir o pagamento a terceiro. Pagamento anterior à ciência da ação libera o devedor, salvo prova de que conhecia o fato.", "A ação judicial protege o proprietário e, ao mesmo tempo, o devedor de boa-fé que ainda ignorava a disputa.", "Após furto do título, o proprietário ajuíza pedido de substituição e comunica o devedor para bloquear o pagamento.", "A exoneração depende da data e da boa-fé do pagamento. Depois de cientificado, o devedor deve respeitar a medida judicial.", "Desapossamento", "perda da posse por ato de outra pessoa, sem consentimento legítimo"),
    "910": row("O endosso é escrito no verso ou anverso do título; no verso basta a assinatura. A transferência se completa com a entrega, e endosso cancelado considera-se não escrito.", "Assinatura e tradição formam o modo típico de circulação do título à ordem, observada a identificação do endossatário quando feita.", "Titular assina o verso e entrega o título ao adquirente, completando a transferência.", "Assinatura isolada no anverso pode ter outra função; forma, posição, entrega e eventual cancelamento precisam ser conferidos em conjunto.", "Tradição", "entrega do título ao adquirente para completar a transferência"),
    "911": row("É possuidor legítimo quem apresenta série regular e ininterrupta de endossos, ainda que o último esteja em branco. Quem paga verifica a cadeia, mas não a autenticidade das assinaturas.", "A legitimidade resulta da continuidade formal dos endossos, sem impor ao pagador perícia sobre cada assinatura.", "Devedor confere que cada endossatário transferiu o título ao seguinte antes de pagar ao último portador.", "Irregularidade visível na cadeia impede presumir legitimação. A dispensa de verificar autenticidade não autoriza ignorar fraude conhecida.", "Série de endossos", "cadeia sucessiva de transferências lançadas no título"),
    "912": row("Condição inserida no endosso é considerada não escrita, e o endosso de apenas parte do valor é nulo.", "O endosso deve transferir o título sem condicionamento cambial nem fracionamento do direito nele incorporado.", "Endosso condicionado a evento futuro circula sem a condição; endosso de metade do título não vale.", "A nulidade do endosso parcial não equivale necessariamente à nulidade do próprio título ou da relação contratual subjacente.", "Endosso parcial", "tentativa de transferir por endosso somente parte do direito do título"),
    "913": row("Quem recebe endosso em branco pode completá-lo com seu nome ou o de terceiro, endossar novamente em branco ou em preto, ou entregar o título sem novo endosso.", "O endosso em branco dá ao portador opções de circulação, inclusive simples tradição.", "Adquirente completa o espaço com seu nome e depois endossa o título a outra pessoa.", "A escolha altera a cadeia documental e a forma de legitimação; devem ser preservadas autenticidade e continuidade dos endossos.", "Endosso em preto", "endosso que identifica nominalmente o endossatário"),
    "914": row("Em regra, o endossante não garante o pagamento, salvo cláusula expressa. Se assumir essa responsabilidade, torna-se devedor solidário e, pagando, pode regressar contra coobrigados anteriores.", "Transferir o título não significa automaticamente garantir sua liquidação, mas a garantia pode ser assumida no próprio endosso.", "Endossante escreve cláusula de garantia, paga o portador e cobra obrigados anteriores.", "A responsabilidade depende de texto expresso e das regras especiais do título; o regresso respeita a posição dos coobrigados.", "Coobrigado", "pessoa que também responde pelo pagamento do título"),
    "915": row("Contra o portador, o devedor pode alegar relações pessoais diretas, forma ou conteúdo literal do título, falsidade da própria assinatura, incapacidade ou representação defeituosa ao assinar e falta de requisito da ação.", "A lei delimita as defesas compatíveis com a autonomia e a literalidade do título à ordem.", "Devedor demonstra que sua assinatura foi falsificada ou que falta requisito para a cobrança.", "Defesas causais contra terceiros anteriores não entram automaticamente nesse rol; má-fé do portador é tratada pelo artigo seguinte.", "Literalidade", "limitação dos direitos e deveres ao que consta formalmente do título"),
    "916": row("Defesa baseada na relação do devedor com portadores anteriores só pode atingir o atual se ele agiu de má-fé ao adquirir o título.", "O terceiro de boa-fé fica protegido de conflitos pessoais anteriores; quem adquire conscientemente para prejudicar o devedor não recebe essa proteção.", "Adquirente sabe do pagamento feito ao portador anterior e compra o título para tentar cobrar novamente.", "A má-fé deve ser demonstrada e existir na aquisição; simples conhecimento posterior do conflito não basta por si só.", "Inoponibilidade", "impedimento de usar determinada defesa contra terceiro protegido"),
    "917": row("O endosso-mandato permite ao endossatário exercer os direitos do título e reendossar apenas como procurador. Mantém eficácia após morte ou incapacidade do endossante, e admite defesas contra este.", "O título é entregue para cobrança ou representação, sem transferência plena do crédito.", "Empresa endossa título ao banco apenas para que ele realize a cobrança.", "Restrições escritas no mandato devem ser observadas. O procurador não passa a proprietário do crédito e suas faculdades derivam do endossante.", "Endosso-mandato", "endosso que concede poderes de representação e cobrança"),
    "918": row("O endosso-penhor dá ao endossatário os direitos do título como garantia; ele só reendossa como procurador. Defesas contra o endossante não o atingem, salvo sua má-fé.", "O crédito do título fica empenhado para assegurar outra obrigação, sem transferência definitiva ao credor pignoratício.", "Devedor entrega por endosso-penhor um título ao banco como garantia de financiamento.", "A cláusula de penhor deve constar do endosso. O exercício dos direitos está ligado à finalidade de garantia e à boa-fé.", "Endosso-penhor", "endosso que vincula o título como garantia de uma dívida"),
    "919": row("Se o título à ordem for adquirido por modo diferente do endosso, a operação produz efeitos de cessão civil.", "A transmissão pode ocorrer, mas sem os efeitos próprios do endosso, sujeitando o adquirente ao regime comum da cessão.", "Crédito do título é transferido por contrato separado, e o adquirente recebe posição de cessionário civil.", "Na cessão, defesas oponíveis ao cedente podem alcançar o cessionário conforme as regras civis; não se presume proteção cambial do endosso.", "Cessão civil", "transferência comum de um crédito entre cedente e cessionário"),
    "920": row("O endosso realizado depois do vencimento produz os mesmos efeitos do endosso anterior ao vencimento.", "O simples fato de o título estar vencido não transforma a transferência em cessão civil sob a regra geral do Código.", "Titular endossa título já vencido e o adquirente recebe os efeitos normais do endosso.", "Leis especiais de determinados títulos podem conter disciplina própria; deve-se verificar qual norma rege o documento.", "Endosso póstumo", "endosso lançado depois do vencimento do título"),
    "921": row("Título nominativo é aquele emitido em favor de pessoa cujo nome consta do registro mantido pelo emitente.", "A titularidade depende da correspondência entre o documento e o registro do emissor.", "Companhia registra determinado investidor como titular de título nominativo.", "A posse isolada do documento não substitui a inscrição registral exigida para essa categoria.", "Título nominativo", "título cujo titular é identificado no registro do emitente"),
    "922": row("O título nominativo transfere-se por termo no registro do emitente, assinado pelo proprietário e pelo adquirente.", "A mudança de titular exige ato registral bilateral, não bastando a entrega física do documento.", "Vendedor e comprador assinam no registro do emissor o termo que transfere o título.", "Devem ser observados os poderes de representação e as formalidades do registro; sem o termo, a transferência típica não se completa.", "Termo de transferência", "assento formal de mudança de titular no registro do emitente"),
    "923": row("O título nominativo também pode ser transferido por endosso nominal, mas só produz efeito perante emitente após averbação. O adquirente legitimado pode exigi-la e, quando cabível, obter novo título em seu nome.", "O endosso cria uma cadeia de aquisições, enquanto a atualização do registro torna a mudança oponível ao emissor.", "Comprador recebe endosso com seu nome e apresenta a cadeia autenticada para averbação.", "O emitente pode exigir prova da autenticidade; o endossatário precisa demonstrar série regular e assinaturas, conforme o caso.", "Averbação", "anotação da transferência no registro mantido pelo emitente"),
    "924": row("Salvo proibição legal, o proprietário pode pedir, às suas custas, que título nominativo seja transformado em título à ordem ou ao portador.", "A forma de circulação pode ser alterada por iniciativa do titular quando a lei não vedar.", "Titular solicita ao emitente a conversão para título à ordem e paga as despesas.", "A conversão em título ao portador continua sujeita à autorização legal exigida para essa modalidade.", "Conversão do título", "mudança formal da espécie e do modo de circulação do documento"),
    "925": row("O emitente que, de boa-fé, efetua a transferência pelos modos previstos fica liberado de responsabilidade.", "Cumpridas as formalidades e ausentes sinais de irregularidade, o emissor não responde por ter reconhecido a transmissão.", "Emitente averba cadeia regular sem conhecer fraude oculta e fica desonerado.", "A proteção exige boa-fé e observância dos modos legais; ciência de fraude ou falha formal pode afastá-la.", "Desoneração", "liberação de responsabilidade pelo ato praticado regularmente"),
    "926": row("Negócio ou medida judicial sobre título nominativo só produz efeito perante o emitente ou terceiros depois de averbado no registro do emitente.", "A averbação dá publicidade e oponibilidade externa aos atos que afetam o título.", "Penhora do título é averbada para que emitente e terceiros tenham de respeitá-la.", "O ato pode vincular seus participantes antes da averbação, mas não será oponível ao emitente e a terceiros nos termos do artigo.", "Oponibilidade", "aptidão de um ato para produzir efeitos contra terceiros"),
    "927": row("Quem causa dano por ato ilícito deve repará-lo. A responsabilidade independe de culpa quando a lei assim determina ou quando a atividade normalmente exercida cria, por sua natureza, risco para direitos alheios.", "A regra combina responsabilidade subjetiva, que exige culpa, com hipóteses objetivas legais ou decorrentes de atividade de risco.", "Empresa que desenvolve atividade naturalmente perigosa indeniza dano ligado ao risco mesmo sem prova de culpa.", "Responsabilidade objetiva não dispensa dano e nexo causal. O risco deve decorrer da natureza da atividade habitual, não de qualquer atividade econômica.", "Responsabilidade objetiva", "dever de indenizar que não depende de prova de culpa"),
    "928": row("O incapaz indeniza o dano que causar se seus responsáveis não tiverem dever de fazê-lo ou não possuírem meios. A indenização é equitativa e não pode privá-lo, nem seus dependentes, do necessário.", "A responsabilidade patrimonial do incapaz é subsidiária e limitada pela proteção de sua subsistência.", "Responsável sem recursos não consegue indenizar, e o juiz fixa valor compatível com o patrimônio do incapaz.", "Não há responsabilidade automática ou integral: verificam-se primeiro os responsáveis, a suficiência de meios e o limite de equidade.", "Indenização equitativa", "reparação ajustada pelo juiz às circunstâncias e à capacidade patrimonial"),
    "929": row("Quando alguém sacrifica coisa alheia ou lesa pessoa para remover perigo iminente, a vítima sem culpa pelo perigo tem direito à indenização.", "Embora o ato possa ser lícito pelo estado de necessidade, o prejuízo do terceiro inocente deve ser reparado.", "Para evitar acidente maior, motorista danifica muro de terceiro que não criou o perigo e deve indenizá-lo.", "O artigo remete ao estado de necessidade do art. 188, II; culpa da vítima pelo perigo pode alterar a solução.", "Estado de necessidade", "ato praticado para afastar perigo iminente nas condições legais"),
    "930": row("Quem indeniza dano praticado em estado de necessidade pode regressar contra o terceiro culpado pelo perigo; na legítima defesa, pode regressar contra a pessoa em defesa de quem causou o dano.", "O custo final é deslocado para quem originou o risco ou foi beneficiado pela atuação defensiva, nas hipóteses legais.", "Motorista indeniza dono do muro e cobra do terceiro que provocou o perigo.", "A ação regressiva exige o pagamento e a demonstração dos pressupostos da hipótese correspondente.", "Ação regressiva", "cobrança de quem deve suportar definitivamente valor pago por outra pessoa"),
    "931": row("Empresários individuais e empresas respondem, sem necessidade de prova de culpa, pelos danos causados por produtos postos em circulação, ressalvadas outras regras de lei especial.", "A responsabilidade objetiva recai sobre o risco do produto introduzido no mercado.", "Produto fabricado com defeito causa lesão e a empresa responde independentemente de culpa.", "Leis especiais, especialmente de proteção do consumidor, podem definir sujeitos, defeitos, excludentes e prazos específicos.", "Produto em circulação", "bem colocado no mercado pelo empresário ou empresa"),
    "932": row("Também respondem pelos danos de terceiros: pais por filhos menores sob autoridade e companhia; tutor e curador por assistidos nessas condições; empregador por prepostos no trabalho ou em razão dele; hospedeiros por hóspedes e educandos; e beneficiários gratuitos do crime até o proveito recebido.", "A lei atribui responsabilidade a pessoas ligadas ao causador ou beneficiadas pelo ilícito, dentro de requisitos próprios.", "Empregador responde por dano causado por empregado durante serviço relacionado à função.", "Cada inciso tem pressupostos específicos. Parentesco, emprego ou hospedagem isolados não bastam fora das condições legais.", "Responsabilidade por fato de terceiro", "dever de reparar dano causado diretamente por outra pessoa"),
    "933": row("As pessoas enumeradas no artigo anterior respondem pelos atos dos terceiros indicados mesmo sem culpa própria.", "Não é preciso provar falha de vigilância ou escolha do responsável indireto; basta preencher a hipótese legal e os demais elementos do dano.", "Vítima cobra empregador sem demonstrar que ele escolheu mal o empregado.", "A ausência de culpa do responsável não elimina possíveis defesas sobre fato, nexo, dano ou ausência da relação prevista no art. 932.", "Culpa presumida", "expressão histórica para responsabilidade que a lei hoje impõe sem prova de culpa própria"),
    "934": row("Quem paga indenização por dano de terceiro pode cobrar dele o valor, salvo quando o causador é seu descendente absoluta ou relativamente incapaz.", "O responsável indireto tem, em regra, direito de regresso contra o autor material, preservada a exceção familiar protetiva.", "Empregador indeniza vítima e busca regresso contra empregado responsável pelo dano.", "O regresso exige pagamento e responsabilidade do causador; a exceção legal impede cobrança contra descendente incapaz.", "Autor material", "pessoa que praticou diretamente o ato causador do dano"),
    "935": row("A responsabilidade civil é independente da criminal, mas a decisão penal definitiva sobre existência do fato ou autoria não pode ser rediscutida no juízo civil.", "As esferas podem seguir separadamente, porém certos pontos decididos de modo vinculante no processo penal estabilizam-se para a ação indenizatória.", "Condenação penal definitiva reconhece autoria, e o réu não pode negá-la depois na ação civil.", "Nem toda absolvição penal elimina o dever civil; é indispensável examinar o fundamento da decisão e o que efetivamente ficou decidido.", "Independência das instâncias", "autonomia relativa entre as consequências civis e criminais do mesmo fato"),
    "936": row("O dono ou detentor do animal deve indenizar o dano causado por ele, salvo se provar culpa da vítima ou força maior.", "A guarda do animal gera responsabilidade, com excludentes legais cuja prova cabe ao responsável.", "Cão escapa e fere pedestre; o guardião indeniza se não demonstrar excludente.", "Caso fortuito comum não aparece como excludente textual; a defesa deve caracterizar culpa da vítima ou força maior e romper o nexo.", "Detentor", "quem exerce guarda ou controle de fato sobre o animal"),
    "937": row("O dono do edifício ou construção responde pelo dano causado por ruína decorrente de reparos manifestamente necessários que não foram feitos.", "A responsabilidade liga o prejuízo à omissão de manutenção diante de necessidade evidente.", "Parte de fachada deteriorada cai e atinge veículo porque o proprietário ignorou reparo visivelmente urgente.", "É preciso relacionar ruína, necessidade manifesta de reparo e dano; outros defeitos construtivos podem seguir regimes diferentes.", "Ruína", "desabamento ou desprendimento decorrente da deterioração da construção"),
    "938": row("Quem habita prédio ou parte dele responde pelo dano causado por coisas que dali caem ou são lançadas em local indevido.", "A lei atribui ao ocupante o risco decorrente de objetos provenientes do espaço habitado.", "Objeto lançado de apartamento danifica automóvel na rua e o habitante responde.", "A identificação do espaço de origem e da pessoa que o habita é relevante; condomínio e múltiplos ocupantes podem exigir análise do caso.", "Coisa lançada", "objeto arremessado ou descartado a partir do prédio"),
    "939": row("Credor que cobra judicialmente antes do vencimento, fora das permissões legais, deve aguardar o prazo restante, descontar os juros correspondentes e pagar custas em dobro.", "A cobrança prematura indevida gera sanções específicas e preserva ao devedor o prazo contratado.", "Credor ajuíza ação meses antes do vencimento sem hipótese de antecipação legal.", "A norma exige demanda e dívida ainda não vencida; vencimento antecipado válido ou autorização legal pode afastar a sanção.", "Cobrança prematura", "demanda proposta antes de a obrigação se tornar exigível"),
    "940": row("Quem demanda por dívida já paga sem descontar o recebido deve pagar o dobro do cobrado; quem pede mais do que o devido paga o equivalente ao excesso, salvo prescrição.", "A lei pune a cobrança judicial abusiva de valor extinto ou superior ao crédito real.", "Credor processa devedor pelo total apesar de já ter recebido metade e responde pela sanção cabível.", "A aplicação considera os requisitos construídos pela legislação e jurisprudência, inclusive a conduta do cobrador; mero erro justificável deve ser distinguido de cobrança indevida sancionável.", "Repetição em dobro", "sanção de devolução ou pagamento correspondente ao dobro do valor indevidamente cobrado"),
    "941": row("As sanções dos arts. 939 e 940 não incidem se o autor desiste antes de o réu contestar, mas permanece possível indenizar prejuízo comprovado do réu.", "A desistência tempestiva afasta as penas civis especiais, sem apagar dano efetivamente causado.", "Credor percebe o erro e desiste antes da contestação; o réu ainda prova gastos extraordinários e pede reparação.", "O marco é anterior à contestação. Custas, honorários processuais e indenização seguem seus regimes próprios.", "Contestação", "defesa formal apresentada pelo réu no processo"),
    "942": row("O patrimônio do responsável garante a reparação; havendo vários autores, todos respondem solidariamente. Coautores e responsáveis do art. 932 também integram a solidariedade.", "A vítima pode exigir a reparação integral de qualquer corresponsável, com acerto interno posterior.", "Dois agentes causam juntos um dano, e a vítima cobra o total de um deles.", "Solidariedade exige participação ou enquadramento legal; quem paga além de sua parte pode ter direito de regresso.", "Solidariedade", "responsabilidade que permite ao credor cobrar o total de qualquer devedor solidário"),
    "943": row("O direito de cobrar reparação e a obrigação de indenizar transmitem-se aos herdeiros.", "A morte não extingue automaticamente o crédito nem o débito indenizatório, que ingressam na sucessão.", "Herdeiros da vítima prosseguem na cobrança, ou o espólio do ofensor responde pela obrigação.", "A responsabilidade dos herdeiros devedores limita-se às forças da herança; direitos personalíssimos devem ser distinguidos do crédito transmissível.", "Transmissão hereditária", "passagem de direitos e obrigações patrimoniais pela sucessão"),
    "944": row("A indenização corresponde à extensão do dano, mas o juiz pode reduzi-la equitativamente quando houver desproporção excessiva entre culpa e prejuízo.", "A reparação busca recompor o dano; excepcionalmente, a equidade evita resultado manifestamente desproporcional.", "Dano muito elevado decorre de culpa mínima, e o juiz avalia redução fundamentada.", "A redução não é automática nem autoriza ignorar a reparação integral sem desproporção excessiva; danos materiais e extrapatrimoniais exigem avaliação própria.", "Extensão do dano", "medida dos prejuízos efetivamente causados à vítima"),
    "945": row("Se a própria vítima contribuiu culposamente para o dano, a indenização é fixada comparando a gravidade de sua culpa com a do autor.", "A culpa concorrente reduz a reparação de forma proporcional à contribuição causal e à gravidade das condutas.", "Pedestre e motorista agem com imprudência, e o juiz reparte o peso das culpas ao calcular a indenização.", "É necessária contribuição causal da vítima; comportamento irrelevante para o resultado não justifica redução.", "Culpa concorrente", "participação culposa da vítima na produção do próprio dano"),
    "946": row("Quando a obrigação é indeterminada e lei ou contrato não fixam a indenização, as perdas e danos são apuradas conforme a legislação processual.", "O valor não definido previamente deve ser liquidado por procedimento adequado, com prova do prejuízo.", "Sentença reconhece dever de indenizar e fase posterior calcula o montante por perícia.", "A apuração processual não dispensa prova do dano nem autoriza valor arbitrário; regras específicas prevalecem quando existentes.", "Liquidação", "procedimento para determinar o valor de obrigação já reconhecida"),
    "947": row("Se o devedor não puder cumprir exatamente a prestação ajustada, ela é substituída por seu valor em dinheiro.", "A impossibilidade da prestação específica converte o dever em equivalente pecuniário.", "Bem devido não pode mais ser entregue e o devedor paga seu valor corrente.", "O equivalente monetário não exclui automaticamente perdas e danos adicionais quando seus pressupostos estiverem presentes.", "Prestação específica", "objeto ou conduta exata prometida na obrigação"),
    "948": row("No homicídio, sem excluir outras reparações, a indenização inclui tratamento, funeral, luto da família e alimentos a quem a vítima os devia, considerada sua provável duração de vida.", "A reparação cobre despesas decorrentes da morte e a perda do sustento legitimamente esperado pelos dependentes.", "Familiares recebem despesas funerárias e pensão correspondente ao suporte que a vítima prestaria.", "Valores, beneficiários e duração dependem de prova e das circunstâncias; a enumeração não impede outros danos demonstrados.", "Pensão indenizatória", "pagamento destinado a compensar sustento perdido pela morte da vítima"),
    "949": row("Em lesão ou ofensa à saúde, o causador paga tratamento, lucros cessantes até o fim da recuperação e outros prejuízos comprovados.", "A reparação alcança despesas médicas, renda perdida durante convalescença e danos adicionais ligados à lesão.", "Vítima recebe gastos de fisioterapia e remuneração que deixou de ganhar enquanto se recuperava.", "Cada parcela exige nexo e prova adequada; incapacidade permanente recebe disciplina complementar do art. 950.", "Lucros cessantes", "ganhos que a vítima razoavelmente deixou de obter por causa do dano"),
    "950": row("Se a lesão impede ou reduz a capacidade profissional, a indenização inclui tratamento, lucros cessantes até a recuperação e pensão pela perda laboral. A vítima pode pedir pagamento da indenização de uma só vez.", "A pensão compensa incapacidade total ou parcial para o trabalho, conforme a importância econômica da atividade afetada.", "Trabalhador perde metade da capacidade e recebe pensão correspondente à depreciação.", "O pagamento em parcela única depende de arbitramento judicial e não equivale necessariamente à soma aritmética de todas as parcelas futuras.", "Depreciação laboral", "redução permanente da capacidade de exercer trabalho ou profissão"),
    "951": row("As indenizações dos arts. 948 a 950 também se aplicam ao profissional que, por negligência, imprudência ou imperícia, mata paciente, agrava doença, causa lesão ou incapacidade laboral.", "A responsabilidade profissional por erro culposo pode gerar as mesmas parcelas previstas para morte e lesões.", "Profissional age com imperícia e causa incapacidade, respondendo por despesas, perdas e pensão cabíveis.", "O artigo exige culpa profissional e nexo causal; resultado adverso ou insucesso terapêutico, sozinho, não prova responsabilidade.", "Imperícia", "falta de conhecimento ou habilidade técnica exigível ao profissional"),
    "952": row("Na usurpação ou esbulho, além de devolver a coisa, o responsável paga deteriorações e lucros cessantes; se ela faltar, reembolsa equivalente pelo preço comum mais valor de afeição limitado àquele.", "A reparação protege a posse ou propriedade e compensa tanto a perda material quanto o uso econômico frustrado.", "Quem toma e destrói bem alheio paga seu preço ordinário, afeição dentro do limite e ganhos perdidos.", "Valor afetivo não pode superar o preço ordinário. Restituição, equivalente e demais parcelas não devem gerar duplicidade.", "Esbulho", "retirada injusta da posse de um bem"),
    "953": row("Dano causado por injúria, difamação ou calúnia deve ser reparado; se não houver prova de prejuízo material, o juiz fixa equitativamente a indenização conforme o caso.", "Ofensas à honra podem gerar reparação mesmo sem perda econômica quantificável.", "Pessoa difamada sem dano financeiro comprovável recebe valor arbitrado pelas circunstâncias da ofensa.", "A indenização exige ato lesivo, dano e nexo; liberdade de expressão, contexto e demais direitos fundamentais devem ser considerados.", "Dano à honra", "lesão à dignidade ou reputação da pessoa"),
    "954": row("Ofensa à liberdade pessoal gera perdas e danos e, sem prova de prejuízo, indenização equitativa. Incluem-se cárcere privado, prisão por acusação falsa e de má-fé e prisão ilegal.", "A privação ilegítima da liberdade é reparável mesmo quando o prejuízo econômico não pode ser demonstrado.", "Vítima de denúncia deliberadamente falsa que leva à prisão pede indenização.", "A lista legal exige análise dos requisitos de cada hipótese; prisão posteriormente revogada não é automaticamente ilícita ou fundada em má-fé.", "Cárcere privado", "privação ilegal da liberdade de locomoção por particular"),
    "955": row("A insolvência é declarada quando o total das dívidas supera o valor dos bens do devedor.", "O estado patrimonial deficitário permite instaurar o regime legal de concurso entre credores.", "Devedor possui bens de cem mil reais e dívidas de cento e cinquenta mil, podendo ser declarado insolvente.", "A declaração depende do procedimento aplicável; dificuldade momentânea de caixa não equivale necessariamente à insolvência patrimonial.", "Insolvência", "situação em que o patrimônio não basta para pagar todas as dívidas"),
    "956": row("No concurso, credores podem discutir tanto a preferência entre seus créditos quanto nulidade, simulação, fraude ou falsidade de dívidas e contratos.", "A verificação não se limita à ordem de pagamento: também controla a existência e legitimidade dos créditos apresentados.", "Credor contesta contrato simulado usado para criar preferência artificial no concurso.", "A impugnação exige fundamento e prova; divergência sobre prioridade não torna por si só inválido o crédito.", "Concurso de credores", "procedimento de disputa e distribuição do patrimônio insuficiente entre credores"),
    "957": row("Sem título legal de preferência, todos os credores têm igual direito sobre os bens do devedor comum.", "Créditos sem garantia ou privilégio legal concorrem em igualdade, sujeitos ao rateio se o patrimônio não bastar.", "Dois credores quirografários dividem proporcionalmente o produto disponível.", "Preferência não nasce apenas de cláusula privada contra terceiros; precisa de fundamento legal e requisitos de eficácia.", "Credor quirografário", "credor sem garantia real nem privilégio legal"),
    "958": row("A preferência entre credores nasce de privilégio previsto em lei ou de direito real validamente constituído.", "A prioridade no recebimento decorre de categoria reconhecida em lei, como privilégio creditório ou garantia real.", "Hipoteca regularmente constituída fundamenta preferência do credor sobre o bem.", "A existência e o grau da preferência dependem da lei, da constituição válida e, quando exigido, do registro.", "Preferência creditória", "prioridade legal de um crédito no pagamento"),
    "959": row("Credores hipotecários ou privilegiados conservam seus direitos sobre seguro ou indenização pela perda do bem gravado e sobre indenização por desapropriação.", "A garantia ou preferência se sub-roga no valor que substitui economicamente a coisa perdida, danificada ou desapropriada.", "Imóvel hipotecado é desapropriado e a preferência passa à indenização correspondente.", "É necessário identificar o vínculo entre o bem gravado e o valor substitutivo; disputas seguem a ordem e extensão da garantia.", "Sub-rogação real", "transferência da garantia do bem para o valor que o substitui"),
    "960": row("Nos casos do artigo anterior, quem deve o seguro ou a indenização libera-se ao pagar se não houver oposição dos credores hipotecários ou privilegiados.", "A ausência de oposição permite pagamento liberatório, enquanto a oposição impede ignorar direitos preferenciais conhecidos.", "Seguradora paga a indenização sem objeção do credor hipotecário e extingue sua obrigação.", "Ciência de oposição exige cautela e observância do procedimento adequado; pagamento ao destinatário errado pode não liberar o devedor.", "Pagamento liberatório", "pagamento válido que extingue a obrigação do pagador"),
    "961": row("Crédito com direito real prefere a qualquer crédito pessoal; entre os pessoais, o privilegiado prefere ao simples, e o privilégio especial prefere ao geral.", "A lei estabelece hierarquia básica entre garantias reais, privilégios e créditos comuns.", "Produto de bem gravado paga primeiro o credor real antes de credor pessoal simples.", "A ordem pode sofrer incidência de normas especiais, fiscais, trabalhistas, falimentares ou registrais; deve-se examinar o regime aplicável.", "Privilégio especial", "preferência legal vinculada a bens determinados"),
    "962": row("Credores da mesma classe e com igual título de privilégio especial rateiam proporcionalmente se os mesmos bens não bastarem para pagamento integral.", "Sem prioridade interna adicional, o prejuízo é dividido conforme o valor de cada crédito.", "Dois créditos igualmente privilegiados recebem, proporcionalmente, o produto insuficiente do bem.", "O rateio exige mesma classe, mesmo título e concorrência sobre os mesmos bens; prioridades distintas não se confundem.", "Rateio proporcional", "distribuição do valor disponível segundo a proporção de cada crédito"),
    "963": row("Privilégio especial alcança somente bens que a lei expressamente vincula ao crédito; privilégio geral recai sobre bens não sujeitos a direito real nem a privilégio especial.", "A extensão da preferência depende de sua categoria e respeita garantias ou privilégios de grau anterior.", "Crédito por benfeitoria tem privilégio sobre a coisa beneficiada, não sobre todo o patrimônio.", "Não se amplia privilégio por analogia. É indispensável localizar a previsão legal e o bem afetado.", "Bem sujeito", "bem especificamente vinculado pela lei ao pagamento preferencial"),
    "964": row("Têm privilégio especial, sobre bens determinados: custas da arrecadação, salvamento, benfeitorias, construção, cultivo, aluguéis sobre utensílios, crédito autoral sobre exemplares, salário do trabalhador agrícola sobre a colheita e crédito por animais sobre produtos do abate.", "Cada crédito recebe preferência apenas sobre o bem ou produto ao qual sua contribuição está legalmente ligada.", "Trabalhador agrícola recebe preferencialmente do produto da colheita em que trabalhou.", "Os nove incisos têm objetos e limites próprios; normas especiais e direitos reais podem interferir na ordem concreta.", "Privilégio especial", "preferência legal que recai sobre bem ou produto especificamente indicado"),
    "965": row("Têm privilégio geral, na ordem legal: funeral; custas e liquidação; luto moderado; doença final; mantença recente da família; impostos dos períodos indicados; salários domésticos dos últimos seis meses de vida; e demais créditos gerais.", "A preferência alcança o patrimônio residual não afetado a direito real ou privilégio especial e respeita a sequência enumerada.", "Na insolvência do falecido, despesas funerárias adequadas precedem créditos gerais posteriores na lista.", "Períodos, moderação e relação com o falecimento são limites expressos. Legislação especial pode modificar prioridades em procedimentos específicos.", "Privilégio geral", "preferência legal sobre o patrimônio residual, sem vinculação a bem determinado"),
    "966": row("Empresário é quem exerce profissionalmente atividade econômica organizada para produzir ou circular bens ou serviços. Profissional intelectual não é empresário, salvo se sua atividade constituir elemento de empresa.", "A caracterização exige habitualidade, finalidade econômica e organização dos fatores de produção; profissão intelectual isolada permanece fora do regime empresarial.", "Médico que atua pessoalmente em consultório pode não ser empresário; clínica organizada como empresa pode enquadrar-se.", "Ter lucro, auxiliares ou CNPJ não resolve sozinho. É necessário verificar se a atividade intelectual integra estrutura empresarial organizada.", "Elemento de empresa", "inserção da atividade profissional em organização empresarial que supera a atuação pessoal"),
    "967": row("O empresário deve inscrever-se no Registro Público de Empresas Mercantis de sua sede antes de iniciar a atividade.", "O registro é obrigação legal de regularização e publicidade da atividade empresarial.", "Empreendedor apresenta inscrição à Junta Comercial antes de abrir o negócio.", "Em regra, o registro não cria a condição material de empresário, que decorre do exercício da atividade; a falta gera irregularidade e consequências legais.", "Registro mercantil", "inscrição pública dos atos do empresário perante a Junta Comercial"),
    "968": row("A inscrição informa identificação e regime de bens, firma autenticada, capital, objeto e sede. Alterações são averbadas; transformação e procedimentos simplificados do microempreendedor seguem as regras dos parágrafos.", "O registro reúne dados essenciais do empresário e permite atualização, transformação societária e simplificação legal para o MEI.", "Empresário informa firma, capital e atividade e depois averba mudança de endereço.", "Dispensas do MEI dependem da disciplina do CGSIM; simplificação não elimina exigências que a legislação especial mantenha.", "Firma", "nome empresarial sob o qual o empresário exerce a atividade"),
    "969": row("Empresário que abre sucursal, filial ou agência em outra jurisdição registral deve inscrevê-la ali, provando a inscrição original, e também averbar o estabelecimento no registro da sede.", "O estabelecimento secundário recebe publicidade tanto no local onde funciona quanto no cadastro principal.", "Empresa abre filial em outro estado, registra-a na Junta local e averba o ato na Junta da sede.", "A dupla providência registral não cria nova pessoa jurídica; documenta a expansão do mesmo empresário.", "Estabelecimento secundário", "filial, sucursal ou agência situada fora do registro principal"),
    "970": row("Empresários rurais e pequenos empresários devem receber da legislação um regime facilitado para registro e para as consequências jurídicas dessa inscrição.", "A norma orienta a criação de regimes menos burocráticos compatíveis com a realidade desses agentes.", "Lei complementar simplifica registros e obrigações de pequeno empresário.", "O artigo não dispensa sozinho toda formalidade; os benefícios concretos dependem da legislação que os regulamenta.", "Tratamento favorecido", "regime jurídico simplificado ou benéfico previsto para determinado grupo"),
    "971": row("Quem exerce atividade rural como principal profissão pode requerer registro e, depois de inscrito, equipara-se ao empresário registrado. Associação de atividade futebolística habitual e profissional também pode optar e tornar-se empresária.", "Para esses sujeitos, a inscrição tem efeito constitutivo da submissão ao regime empresarial previsto no artigo.", "Produtor rural pede registro mercantil e passa a ser tratado como empresário sujeito a registro.", "A opção exige atividade principal rural ou, para associação, futebol profissional habitual, além das formalidades do art. 968.", "Equiparação", "atribuição dos mesmos efeitos jurídicos de outra categoria após requisito legal"),
    "972": row("Pode exercer atividade de empresário quem está em pleno gozo da capacidade civil e não sofre impedimento legal.", "A aptidão empresarial exige capacidade e ausência de proibição específica ligada à pessoa ou função.", "Adulto plenamente capaz e sem impedimento legal registra e exerce empresa individual.", "Capacidade não elimina impedimentos profissionais ou funcionais previstos em outras leis; exercício irregular pode gerar responsabilidade.", "Impedimento legal", "proibição normativa de exercer atividade empresarial apesar da capacidade civil"),
}


